versions.variantCss:
.wemd-product-card[data-variant="bytedance-product-modern"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  overflow: hidden;
  margin: 16px 0;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-image {
  width: 100%;
  margin: 0;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-image img {
  width: 100%;
  height: auto;
  display: block;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-badge {
  display: inline-block;
  background: var(--wemd-primary);
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  margin: 12px 16px 0 16px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-title {
  color: var(--wemd-text-strong);
  font-size: 17px;
  font-weight: 700;
  margin: 8px 16px 4px 16px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-subtitle {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0 16px 8px 16px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-description {
  color: var(--wemd-text-normal);
  font-size: 14px;
  line-height: 1.7;
  margin: 0 16px 12px 16px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-price-row {
  display: flex;
  align-items: center;
  margin: 0 16px 12px 16px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-price {
  color: var(--wemd-primary);
  font-size: 20px;
  font-weight: 700;
  margin-right: 8px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-original {
  color: var(--wemd-text-soft);
  font-size: 13px;
  text-decoration: line-through;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-meta-row {
  display: flex;
  align-items: center;
  margin: 0 16px 12px 16px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-rating,
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-sales,
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-stock {
  color: var(--wemd-text-soft);
  font-size: 12px;
  margin-right: 12px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-button {
  display: block;
  background: linear-gradient(135deg, var(--wemd-primary), var(--wemd-primary-dark));
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
  text-align: center;
  padding: 10px 16px;
  margin: 0 16px 16px 16px;
  border-radius: 8px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-tags {
  margin: 0 16px 12px 16px;
}
.wemd-product-card[data-variant="bytedance-product-modern"] .wemd-pc-tag {
  display: inline-block;
  background: var(--wemd-primary-light);
  color: var(--wemd-primary);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
  margin-right: 6px;
}
